def search(lst):
    count_dict = {}
    for num in lst:
        if num in count_dict:
            count_dict[num] += 1
        else:
            count_dict[num] = 1

    max_num = -1
    for num in sorted(count_dict.keys(), reverse=True):
        if num >= 1 and count_dict[num] >= num:
            max_num = num
            break

    return max_num

