def search(lst):
    freq = {}
    for num in lst:
        if num in freq:
            freq[num] += 1
        else:
            freq[num] = 1

    max_num = max(lst)
    for num in range(max_num, 0, -1):
        if freq.get(num, 0) >= num:
            return num
    return -1

