def encode(message):
    vowels = 'aeiou'
    encoded_message = ''

    for char in message:
        if char.isalpha():
            if char.isupper():
                encoded_message += char.swapcase()
            else:
                encoded_message += char.upper()

            if char.lower() in vowels:
                index = vowels.index(char.lower())
                new_index = (index + 2) % 5
                encoded_message += vowels[new_index]
            else:
                encoded_message += char
        else:
            encoded_message += char

    return encoded_message

