def choose_num(x, y):
    # Check if x is greater than y
    if x > y:
        return -1

    # Find the biggest even number in the range [x, y]
    for i in range(y, x - 1, -1):
        if i % 2 == 0:
            return i

    # If no even number is found, return -1
    return -1

