def match_parens(lst):
    s1, s2 = lst
    stack = []

    for c in s1 + s2:
        if c == '(':
            stack.append(c)
        elif c == ')':
            if stack:
                stack.pop()
            else:
                stack.append(c)

    return 'Yes' if not stack else 'No'

print(match_parens(['()(', ')']))  # Yes
print(match_parens([')', ')']))  # No

def match_parens(lst):
    open_parens = lst[0].count('(')
    close_parens = lst[0].count(')') + lst[1].count('(')
    if close_parens < open_parens:
        return 'No'
    close_parens -= open_parens
    open_parens = lst[1].count('(') - close_parens
    if open_parens < 0:
        return 'Yes'
    else:
        return 'No'

print(match_parens(['()(', ')']))  # 'Yes'
print(match_parens([')', ')']))  # 'No'

